package com.rotarypumpers.meraki;
import android.app.*;import android.content.*;import android.graphics.Typeface;import android.graphics.drawable.GradientDrawable;import android.view.*;import android.widget.*;import android.text.*;import org.json.*;import com.rotarypumpers.meraki.core.*;import java.time.*;import java.util.*;
/** White recipe form. Saving never applies commands to the machine. */
final class RecipeEditor{
 interface Save{void save(JSONObject recipe,JSONObject bag,boolean photo)throws Exception;}
 private final Activity owner;private final Context c;private final BagStore bags;private final JSONObject original;private final Save save;private final LinearLayout form;private final Map<String,EditText> fields=new HashMap<>();private JSONObject bag;private TextView bagLabel,ratio;private Switch window;private Spinner pi,home,background;private AlertDialog dialog;private String validationError="";private static final int INK=0xff20261e,MUTED=0xff586052,GREEN=0xff35542d;
 RecipeEditor(Activity owner,JSONObject original,Save save)throws Exception{this.owner=owner;this.c=LightDialogs.context(owner);this.original=original;this.save=save;bags=new BagStore(owner.getFilesDir());bag=original==null?null:bags.find(original.optString("bag_id"));form=new LinearLayout(c);form.setOrientation(1);form.setPadding(dp(16),dp(8),dp(16),dp(12));build();}
 private int dp(int n){return Math.round(n*c.getResources().getDisplayMetrics().density);}private TextView text(String value,int size,int color){TextView t=new TextView(c);t.setText(value);t.setTextColor(color);t.setTextSize(size);t.setPadding(0,dp(5),0,dp(5));return t;}
 private void section(String title,String note){TextView t=text(title,15,GREEN);t.setTypeface(null,Typeface.BOLD);t.setPadding(0,dp(18),0,dp(4));form.addView(t);if(!note.isEmpty())form.addView(text(note,12,MUTED));}
 private Button button(String label,Runnable action){Button b=new Button(c);b.setText(label);b.setAllCaps(false);b.setTextSize(13);b.setMinWidth(0);b.setMinimumWidth(0);b.setMinHeight(dp(48));b.setPadding(dp(6),dp(6),dp(6),dp(6));b.setOnClickListener(v->action.run());return b;}
 private EditText field(String key,String label,String fallback){form.addView(text(label,12,MUTED));EditText e=new EditText(c);e.setTextColor(INK);e.setText(original==null?fallback:original.optString(key,fallback));e.setSingleLine(!key.equals("notes"));form.addView(e,new LinearLayout.LayoutParams(-1,-2));fields.put(key,e);return e;}
 private EditText step(String key,String label,double fallback,double delta,double min,double max){LinearLayout row=new LinearLayout(c);row.setGravity(Gravity.CENTER_VERTICAL);row.addView(text(label,14,INK),new LinearLayout.LayoutParams(0,-2,1));EditText e=new EditText(c);e.setTextColor(INK);e.setGravity(Gravity.CENTER);e.setSingleLine();e.setSelectAllOnFocus(true);e.setText(format(original==null?fallback:original.optDouble(key,fallback),delta));e.setInputType(android.text.InputType.TYPE_CLASS_NUMBER|android.text.InputType.TYPE_NUMBER_FLAG_DECIMAL);Button minus=button("−",()->adjust(e,-delta,min,max,delta)),plus=button("+",()->adjust(e,delta,min,max,delta));minus.setContentDescription("Decrease "+label);plus.setContentDescription("Increase "+label);row.addView(minus,new LinearLayout.LayoutParams(dp(44),dp(48)));row.addView(e,new LinearLayout.LayoutParams(dp(66),dp(52)));row.addView(plus,new LinearLayout.LayoutParams(dp(44),dp(48)));form.addView(row);fields.put(key,e);return e;}
 private String format(double value,double step){return String.format(Locale.US,step<1?"%.1f":"%.0f",value);}private void adjust(EditText e,double d,double min,double max,double step){try{double n=Double.parseDouble(e.getText().toString());e.setText(format(Math.max(min,Math.min(max,n+d)),step));}catch(Exception ex){Toast.makeText(owner,"Enter a number first",Toast.LENGTH_SHORT).show();}}
 private Spinner choices(String label,String[] items,int selected){form.addView(text(label,12,MUTED));Spinner s=new Spinner(c);s.setAdapter(new ArrayAdapter<String>(c,android.R.layout.simple_spinner_dropdown_item,items));s.setSelection(selected);form.addView(s,new LinearLayout.LayoutParams(-1,dp(48)));return s;}
 private void build(){
  field("name","Recipe name","House Espresso");section("Sent to the machine","Applied only when you use the recipe.");step("dose_g","Dose (g)",18,.1,1,30.9);step("yield_g","Yield (g)",36,1,10,99);step("brew_c","Temperature (°C)",93,1,85,96);ratio=text("",14,GREEN);form.addView(ratio);TextWatcher watcher=new TextWatcher(){public void beforeTextChanged(CharSequence s,int a,int b,int n){}public void onTextChanged(CharSequence s,int a,int b,int n){ratio();}public void afterTextChanged(Editable e){}};fields.get("dose_g").addTextChangedListener(watcher);fields.get("yield_g").addTextChangedListener(watcher);ratio();String mode=original==null?"keep":original.optString("preinfusion_mode","keep");pi=choices("Pre-infusion",RecipePreinfusion.LABELS,mode.equals("on")?1:mode.equals("off")?2:0);form.addView(text("On/Off only. Pressure and duration stay as set on the machine.",12,MUTED));
  section("You set","Shown as a reminder; grind size stays manual.");step("grind","Grind size",13,1,0,100);
  section("Shot time window","A check on the result; never sent to the machine.");window=new Switch(c);window.setText("Use shot time window");window.setTextColor(INK);window.setMinHeight(dp(48));window.setChecked(ShotTimeWindow.enabled(original));form.addView(window);step("time_s","From (s)",25,1,1,179);step("time_max_s","To (s)",32,1,2,180);Runnable enabled=()->{for(String k:new String[]{"time_s","time_max_s"}){EditText e=fields.get(k);ViewGroup row=(ViewGroup)e.getParent();for(int i=0;i<row.getChildCount();i++)row.getChildAt(i).setEnabled(window.isChecked());row.setAlpha(window.isChecked()?1:.45f);}};window.setOnCheckedChangeListener((v,on)->enabled.run());enabled.run();
  section("Bean / bag","Set once per bag. Each shot keeps its age at brew time.");bagLabel=text("",13,INK);form.addView(bagLabel);bagLabel();form.addView(button("Choose bag…",this::chooseBag));form.addView(button("Set roast date…",()->setDate("roast_date")));form.addView(button("Set opened date…",()->setDate("opened_date")));form.addView(button("Edit brand…",this::editBrand));form.addView(button("New bag today",()->{try{newBag(true);}catch(Exception e){error(e);}}));
  section("Machine Home screen","");home=choices("Home color",HomeAppearance.LABELS,Math.max(0,HomeAppearance.index(original==null?"standard":original.optString("home_color","standard"))));EditText homeName=field("home_name","Home name",original==null?"House Espresso":HomeAppearance.suggest(original.optString("name")));homeName.setFilters(new InputFilter[]{new InputFilter.LengthFilter(24)});final boolean[] customName={original!=null&&!original.optString("home_name").isEmpty()&&!original.optString("home_name").equals(HomeAppearance.suggest(original.optString("name")))},settingName={false};homeName.addTextChangedListener(new TextWatcher(){public void beforeTextChanged(CharSequence v,int a,int n,int x){}public void onTextChanged(CharSequence v,int a,int b,int n){if(!settingName[0])customName[0]=true;}public void afterTextChanged(Editable v){}});fields.get("name").addTextChangedListener(new TextWatcher(){public void beforeTextChanged(CharSequence v,int a,int n,int x){}public void onTextChanged(CharSequence v,int a,int b,int n){if(!customName[0]){settingName[0]=true;homeName.setText(HomeAppearance.suggest(v.toString()));settingName[0]=false;}}public void afterTextChanged(Editable v){}});
  section("Record card","");String style=RecipeBackground.mode(original);background=choices("Background",new String[]{"Standard background","Recipe Home color","Product photo"},style.equals("home_color")?1:style.equals("photo")?2:0);form.addView(button("Save & choose product photo…",()->commit(true)));form.addView(text("Photo selection saves recipe edits first. Cancelling keeps the previous background.",12,MUTED));section("Notes","");field("notes","Optional notes","");
 }
 private void ratio(){try{double d=number("dose_g"),y=number("yield_g");ratio.setText(d>0?String.format(Locale.US,"Ratio  1 : %.2f",y/d):"Ratio —");}catch(Exception e){ratio.setText("Ratio —");}}
 private double number(String key){try{return Double.parseDouble(fields.get(key).getText().toString().trim());}catch(Exception e){throw new IllegalArgumentException("Enter a valid number for "+key.replace("_g","").replace("_c","").replace("_s","").replace("_"," "));}}
 private void bagLabel(){
  if(bag==null){bagLabel.setText("No bag selected · age unknown");return;}
  bagLabel.setText(BagTracking.current(bag)+"\nBrand · "+bag.optString("brand","Unknown brand")
   +"\nRoasted on · "+bag.optString("roast_date","Not set")
   +"\nOpened on · "+bag.optString("opened_date","Not set"));
 }
 private void editBrand(){
  if(bag==null){Toast.makeText(owner,"Choose or create a bag first",Toast.LENGTH_SHORT).show();return;}
  EditText input=new EditText(c);
  input.setSingleLine();
  input.setFilters(new android.text.InputFilter[]{new android.text.InputFilter.LengthFilter(80)});
  input.setText(bag.optString("brand"));
  LightDialogs.builder(owner).setTitle("Bean brand").setView(input)
   .setNegativeButton("Cancel",null).setPositiveButton("Save",(dialog,which)->{
    try{bag.put("brand",input.getText().toString());bag=BagTracking.validate(bag);bagLabel();}
    catch(Exception e){error(e);}
   }).show();
 }
 private void newBag(boolean opened){EditText name=new EditText(c);name.setSingleLine();name.setText(bag==null?fields.get("name").getText():bag.optString("name"));AlertDialog d=LightDialogs.builder(owner).setTitle(opened?"New bag opened today":"New bag").setMessage("This creates a separate bag; earlier shots keep their saved ages.").setView(name).setNegativeButton("Cancel",null).setPositiveButton("Use bag",null).create();d.setOnShowListener(v->d.getButton(-1).setOnClickListener(w->{try{JSONObject b=new JSONObject().put("id",UUID.randomUUID().toString()).put("name",name.getText().toString());if(opened)b.put("opened_date",LocalDate.now().toString());bag=BagTracking.validate(b);bagLabel();d.dismiss();}catch(Exception e){error(e);}}));d.show();}
 private void chooseBag(){try{JSONArray all=bags.load();String[] names=new String[all.length()+2];names[0]="No bag / age unknown";names[1]="Create a new bag…";for(int i=0;i<all.length();i++)names[i+2]=BagTracking.current(all.getJSONObject(i));LightDialogs.builder(owner).setTitle("Choose bag").setItems(names,(d,w)->{try{if(w==0)bag=null;else if(w==1){newBag(false);return;}else bag=new JSONObject(all.getJSONObject(w-2).toString());bagLabel();}catch(Exception e){error(e);}}).setNegativeButton("Cancel",null).show();}catch(Exception e){error(e);}}
 private void setDate(String key){if(bag==null){Toast.makeText(owner,"Choose or create a bag first",Toast.LENGTH_SHORT).show();return;}LocalDate initial=LocalDate.now();try{initial=LocalDate.parse(bag.optString(key,initial.toString()));}catch(Exception e){}DatePickerDialog picker=new DatePickerDialog(c,(view,y,m,d)->{try{bag.put(key,LocalDate.of(y,m+1,d).toString());bag=BagTracking.validate(bag);bagLabel();}catch(Exception e){error(e);}},initial.getYear(),initial.getMonthValue()-1,initial.getDayOfMonth());picker.getDatePicker().setMaxDate(System.currentTimeMillis());picker.setButton(DialogInterface.BUTTON_NEUTRAL,"Clear",(dialog,which)->{bag.remove(key);bagLabel();});picker.show();}
 private void commit(boolean photo){try{JSONObject r=new JSONObject();r.put("id",original==null?UUID.randomUUID().toString():original.getString("id")).put("name",fields.get("name").getText().toString().trim()).put("notes",fields.get("notes").getText().toString());for(String key:new String[]{"dose_g","yield_g","brew_c","grind"})r.put(key,number(key));new RecipeControls.Plan(r.getDouble("brew_c"),r.getDouble("yield_g"),r.getDouble("dose_g"),Double.NaN);r.put("shot_time_window",window.isChecked());if(window.isChecked()){double lo=number("time_s"),hi=number("time_max_s");if(lo<1||hi>180||lo>=hi||lo!=Math.rint(lo)||hi!=Math.rint(hi))throw new IllegalArgumentException("Enter whole seconds with From less than To (1–180 s)");r.put("time_s",lo).put("time_max_s",hi);}r.put("preinfusion_mode",RecipePreinfusion.MODES[pi.getSelectedItemPosition()]).put("home_color",HomeAppearance.COLORS[home.getSelectedItemPosition()]).put("home_name",fields.get("home_name").getText().toString().trim());if(bag!=null)r.put("bag_id",bag.getString("id"));if(original!=null)RecipeBackground.copy(original,r);String style=background.getSelectedItemPosition()==1?"home_color":background.getSelectedItemPosition()==2?"photo":"standard";boolean needsPhoto=photo||(style.equals("photo")&&r.optString("record_photo").isEmpty());if(!needsPhoto)r.put("record_background",style);save.save(RecipeStore.validate(r),bag,needsPhoto);dialog.dismiss();}catch(Exception e){error(e);}}
 private void error(Exception e){validationError=e.toString();Toast.makeText(owner,e.getMessage()==null?"Could not save recipe":e.getMessage(),Toast.LENGTH_LONG).show();}
 void show(){ScrollView scroll=new ScrollView(c);scroll.setFillViewport(false);scroll.addView(form);dialog=LightDialogs.builder(owner).setTitle(original==null?"New recipe":"Edit recipe").setView(scroll).setNegativeButton("Cancel",null).setPositiveButton("Save recipe",null).create();dialog.setOnShowListener(v->{dialog.getButton(-1).setOnClickListener(w->commit(false));int height=(int)(owner.getResources().getDisplayMetrics().heightPixels*.88);dialog.getWindow().setLayout(-1,height);dialog.getWindow().setSoftInputMode(WindowManager.LayoutParams.SOFT_INPUT_ADJUST_RESIZE);});dialog.show();}
}
